const PLACEHOLDER_HOST = 'https://replace-before-release.invalid/';

/** True for a placeholder or anything that is not a plain https link. */
export function isPlaceholderUrl(url: string): boolean {
  return url.startsWith(PLACEHOLDER_HOST) || !/^https:\/\/[^\s/]+\.[^\s/]+/.test(url) || /\.invalid(\/|$)/.test(url);
}

